VALUES ('deepseek-aed2a32c', 'deepseek', 'https://app.mokahr.com/social-recruitment/high-flyer/140576#/job/aed2a32c-189f-4338-b901-9b45d2b7edfd', 'full_time,intern', 'open', 0, 46, NULL, 1791905400000, 1791905400000)
